// Validate the agent payload and keep only the fields we store.
const ALLOWED_EVENTS = ['boot', 'logon', 'wake', 'heartbeat', 'shutdown'];

const req = $input.first().json;
const body = req.body && typeof req.body === 'object' ? req.body : {};
const headers = req.headers ?? {};

const clean = (value, max = 200) => {
	if (value === undefined || value === null) return null;
	const text = String(value).trim().slice(0, max);
	return text === '' ? null : text;
};
const toIso = (value) => {
	const ms = value ? Date.parse(value) : NaN;
	return Number.isNaN(ms) ? null : new Date(ms).toISOString();
};

const deviceId = clean(body.deviceId, 100);
const event = (clean(body.event, 20) ?? 'heartbeat').toLowerCase();

const errors = [];
if (!deviceId) errors.push('deviceId is required');
if (!ALLOWED_EVENTS.includes(event)) {
	errors.push(`event must be one of: ${ALLOWED_EVENTS.join(', ')}`);
}

// The first X-Forwarded-For entry is the client when n8n runs behind a proxy.
const forwardedFor = clean(headers['x-forwarded-for'], 300);

return [
	{
		json: {
			valid: errors.length === 0,
			error: errors.join('; '),
			deviceId,
			event,
			hostname: clean(body.hostname),
			serialNumber: clean(body.serialNumber, 100),
			os: clean(body.os),
			osUser: clean(body.osUser),
			localIp: clean(body.localIp, 100),
			publicIp: forwardedFor ? forwardedFor.split(',')[0].trim() : null,
			agentVersion: clean(body.agentVersion, 20),
			bootAt: toIso(body.bootTime),
			receivedAt: new Date().toISOString(),
		},
	},
];

// Decide if this check-in starts a new online session, and build the rows to store.
// Keep OFFLINE_AFTER_MINUTES equal to the value in the "Fleet: offline watchdog" workflow.
const OFFLINE_AFTER_MINUTES = 15;
const LOGGED_EVENTS = ['boot', 'logon', 'shutdown'];

const checkin = $('Normalize check-in').first().json;
// "Find device" returns an empty item when the laptop is not known yet.
const prev = $input.first().json;
const isKnown = Boolean(prev.deviceId);
const now = checkin.receivedAt;

const toIso = (value) => (value ? new Date(value).toISOString() : null);
const pick = (key) => checkin[key] ?? prev[key] ?? null;

const lastSeenMs = prev.lastSeenAt ? new Date(prev.lastSeenAt).getTime() : null;
const gapMinutes =
	lastSeenMs === null ? null : Math.max(0, Math.round((Date.parse(now) - lastSeenMs) / 60000));
const wasOnline =
	isKnown && prev.status === 'online' && gapMinutes !== null && gapMinutes <= OFFLINE_AFTER_MINUTES;

const isShutdown = checkin.event === 'shutdown';
const cameOnline = !isShutdown && (!wasOnline || checkin.event === 'boot');

const device = {
	deviceId: checkin.deviceId,
	hostname: pick('hostname'),
	serialNumber: pick('serialNumber'),
	os: pick('os'),
	osUser: pick('osUser'),
	localIp: pick('localIp'),
	publicIp: pick('publicIp'),
	agentVersion: pick('agentVersion'),
	status: isShutdown ? 'offline' : 'online',
	lastEvent: checkin.event,
	lastSeenAt: now,
	lastOnlineAt: cameOnline ? now : (toIso(prev.lastOnlineAt) ?? now),
	lastOfflineAt: isShutdown ? now : toIso(prev.lastOfflineAt),
	lastBootAt: checkin.bootAt ?? toIso(prev.lastBootAt),
	firstSeenAt: toIso(prev.firstSeenAt) ?? now,
	onlineCount: Number(prev.onlineCount ?? 0) + (cameOnline ? 1 : 0),
};

// Log session changes only. Plain heartbeats update the device row but are not logged.
const event =
	cameOnline || LOGGED_EVENTS.includes(checkin.event)
		? {
				deviceId: device.deviceId,
				hostname: device.hostname,
				event: cameOnline ? 'online' : checkin.event,
				trigger: checkin.event,
				occurredAt: now,
				offlineMinutes: cameOnline && isKnown ? gapMinutes : null,
				osUser: device.osUser,
				localIp: device.localIp,
				publicIp: device.publicIp,
			}
		: null;

return [{ json: { cameOnline, isNewDevice: !isKnown, device, event } }];

// Stop this branch when the check-in is a plain heartbeat.
const event = $input.first().json.event;
return event ? [{ json: event }] : [];
